import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import App from "./App";
import "./index.css";

// Registered by hand: virtual:pwa-register needs workbox-window, a second dependency.
// autoUpdate makes the worker skipWaiting and claim clients, so a new build takes over on its own.
// Dev serves no sw.js, so production only.
if (import.meta.env.PROD && "serviceWorker" in navigator) {
  void navigator.serviceWorker.register("/sw.js", { scope: "/" });
}

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);
import { useSyncExternalStore } from "react";
import { useScreen, type Screen } from "./lib/screen";
import Look from "./screens/Look";
import SceneScreen from "./screens/Scene";
import Roleplay from "./screens/Roleplay";
import Corrections from "./screens/Corrections";
import Review from "./screens/Review";
import Diary from "./screens/Diary";
import Listen from "./screens/Listen";
import Settings from "./screens/Settings";
import TabBar, { useIsFullScreen } from "./components/TabBar";

function subscribeOnline(cb: () => void): () => void {
  window.addEventListener("online", cb);
  window.addEventListener("offline", cb);
  return () => {
    window.removeEventListener("online", cb);
    window.removeEventListener("offline", cb);
  };
}

function Current({ screen }: { screen: Screen }) {
  switch (screen) {
    case "look":
      return <Look />;
    case "scene":
      return <SceneScreen />;
    case "roleplay":
      return <Roleplay />;
    case "corrections":
      return <Corrections />;
    case "review":
      return <Review />;
    case "diary":
      return <Diary />;
    case "settings":
      return <Settings />;
    case "listen":
      return <Listen />;
  }
}

export default function App() {
  const { screen, go } = useScreen();
  const offline = useSyncExternalStore(subscribeOnline, () => !navigator.onLine);
  const fullScreen = useIsFullScreen();
  return (
    <div className="mx-auto flex min-h-dvh max-w-md flex-col">
      {/* Roleplay has its own offline pill. */}
      {offline && screen !== "roleplay" && (
        <p role="status" className="border-b border-line bg-card px-[var(--gutter)] pt-[max(4px,env(safe-area-inset-top))] pb-1 text-[length:var(--text-small)] text-muted">
          offline. noé runs on this device.
        </p>
      )}
      <main className="flex-1">
        <Current screen={screen} />
      </main>
      <TabBar screen={screen} go={go} hidden={fullScreen} />
    </div>
  );
}
# Google Gemini API key, used server-side by api/scene, api/turn, api/correct, api/check, api/translate, api/extract.
GEMINI_API_KEY=
# Gradium API key, used server-side only to mint short-lived browser tokens.
GRADIUM_API_KEY=
# One model per job. Each route reads its own var; GEMINI_MODEL is only a last-resort alias.
# api/scene: vision + JSON on the camera path, flash keeps it under 3 s.
GEMINI_MODEL_VISION=gemini-3.8-flash
# api/turn: text roleplay fallback when Live fails, latency-bound.
GEMINI_MODEL_TURN=gemini-3.8-flash
# api/correct: once per exchange, quality beats speed; falls back to gemini-3.8-flash after 8 s or on error.
GEMINI_MODEL_GRADER=gemini-3.1-pro-preview
# api/live-token: native audio and barge-in with the lowest turn latency.
GEMINI_MODEL_LIVE=gemini-3.8-live
# api/check: trivial transcript vs target comparison, many calls, must feel instant.
GEMINI_MODEL_CHECK=gemini-3.5-flash-lite
# api/level: CEFR classification with JSON at moderate volume.
GEMINI_MODEL_LEVEL=gemini-3.8-flash
# api/translate: one short line per heard utterance in the listen fallback, many calls, must feel instant.
GEMINI_MODEL_TRANSLATE=gemini-3.5-flash-lite
# api/extract: once per listened conversation, picks what to learn with JSON output.
GEMINI_MODEL_EXTRACT=gemini-3.8-flash
# Client build only. native app only: https://<your-vercel-host>. Leave empty for the web app.
VITE_API_BASE=
# Server: extra origins allowed to call /api, comma-separated. The iOS app is https://localhost.
ALLOWED_ORIGINS=
# Client: Supabase project URL (Project Settings > API). Public.
VITE_SUPABASE_URL=
# Client: Supabase anon key. Public; RLS on the Clerk sub protects the data.
VITE_SUPABASE_ANON_KEY=
# Client: Clerk publishable key (pk_...). Public. Signed out, the app stays local-only.
VITE_CLERK_PUBLISHABLE_KEY=
# Supabase CLI config for the hosted project "alltag" (eu-central-2).
# No keys here. CLERK_DOMAIN comes from the environment at `supabase config push` time.
project_id = "alltag"

[api]
enabled = true
schemas = ["public", "storage"]

[db]
major_version = 17

[storage]
enabled = true
file_size_limit = "10MiB"

[auth]
enabled = true

# Clerk is the identity provider. Supabase accepts Clerk session tokens as third-party auth.
[auth.third_party.clerk]
enabled = true
domain = "env(CLERK_DOMAIN)"
-- No seed data. Every row belongs to a signed-in Clerk user and is written by the app's sync.
// Row types for the Supabase tables in supabase/migrations/20261010120000_init.sql.
// This is the contract the sync layer builds on: keep the columns here and in the SQL identical.
// Timestamps are ISO strings as they come back from PostgREST.

export type Level = "A1" | "A2" | "B1" | "B2";

/** Columns every synced table carries. user_id is the Clerk sub. */
export interface SyncColumns {
  user_id: string;
  updated_at: string;
  deleted_at: string | null;
}

export interface ProfileRow extends SyncColumns {
  level: Level | null;
