  MODEL_FILE: "gemma-4-E2B-it-web.task",
  MODEL_LABEL: "Gemma 4 E2B",
  MODEL_LICENCE: { name: "Apache 2.0", url: "https://www.apache.org/licenses/LICENSE-2.0" },
  gemma: fake,
}));

type InstallState = {
  canInstall: boolean;
  install: () => Promise<void>;
  platform: "android" | "ios" | "other";
  installed: boolean;
