    fireEvent.click(screen.getByRole("button", { name: "remove" }));
    expect(confirm).toHaveBeenCalledTimes(2);
    expect(fake.remove).toHaveBeenCalledTimes(1);
  });

  it("links to the model on Hugging Face", () => {
