                    autoComplete={mode === "sign_in" ? "current-password" : "REDACTED"}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className={`${field} min-w-0 flex-1`}
                  />
                  <button
                    type="button"
                    aria-label={show ? "hide password" : "REDACTED"}
                    onClick={() => setShow((s) => !s)}
